// This fixture is generated by the parent repo's offline bigfish_products.py.
// Only the test database enables it; the committed payloads are disabled/hidden.
func setupBigfishProductsTest(t *testing.T) []SubscriptionPlan {
	t.Helper()
	setupMonthlyProductsTest(t)
	data, err := os.ReadFile("testdata/bigfish-draft.json")
	require.NoError(t, err)
	var catalog struct {
		Prices []struct {
			Price ProductPrice `json:"price"`
		} `json:"price_requests"`
		Plans []struct {
			Plan SubscriptionPlan `json:"plan"`
		} `json:"plan_requests"`
	}
	require.NoError(t, common.Unmarshal(data, &catalog))
	require.Len(t, catalog.Prices, 2)
	require.Len(t, catalog.Plans, 3)
	for _, item := range catalog.Prices {
		require.False(t, item.Price.Enabled)
		item.Price.Enabled = true
		require.NoError(t, DB.Create(&item.Price).Error)
	}
	plans := make([]SubscriptionPlan, 0, 3)
	for _, item := range catalog.Plans {
		require.False(t, item.Plan.Enabled)
		require.False(t, item.Plan.Listed)
		require.NoError(t, DB.Create(&item.Plan).Error)
		require.False(t, item.Plan.Enabled)
		require.False(t, item.Plan.Listed)
		require.False(t, item.Plan.RedemptionEnabled)
		require.NoError(t, DB.Model(&item.Plan).Update("enabled", true).Error)
		item.Plan.Enabled = true
		plans = append(plans, item.Plan)
	}
	return plans
}

func TestBigfishDraftCatalogIsSeparateFromMonthlyAndClassroom(t *testing.T) {
	plans := setupBigfishProductsTest(t)
	wantQuota := []int64{4_950_000, 9_950_000, 19_950_000}
	wantPrice := []float64{9.9, 19.9, 39.9}
	for index, plan := range plans {
		assert.Equal(t, wantPrice[index], plan.PriceAmount)
		assert.Equal(t, wantQuota[index], plan.TotalAmount)
		assert.Equal(t, SubscriptionCategoryPackage, plan.Category)
		assert.Equal(t, 15, plan.DurationValue)
		assert.Equal(t, SubscriptionResetNever, plan.QuotaResetPeriod)
		assert.Equal(t, plans[0].ModelScope, plan.ModelScope)
		assert.False(t, *plan.AllowWalletOverflow)
		assert.False(t, plan.CourseEligible)
		broken := plan
		broken.DurationValue = 30
		require.Error(t, broken.ValidateV1Contract())
		broken = plan
		broken.ProductCode = "pro"
		require.Error(t, broken.ValidateV1Contract())
		broken = plan
		broken.MaxPurchasePerUser = 2
		require.Error(t, broken.ValidateV1Contract())
		broken = plan
		broken.ModelScope += ",deepseek-v4-pro-0813"
		require.Error(t, broken.ValidateV1Contract())
	}
	var monthly []SubscriptionPlan
	require.NoError(t, DB.Where("product_type = ?", ProductTypeMonthlySubscription).Order("product_tier").Find(&monthly).Error)
	require.Len(t, monthly, 3)
	for index, plan := range monthly {
		assert.Equal(t, 30, plan.DurationValue)
		assert.Equal(t, []float64{19.9, 49.9, 99.9}[index], plan.PriceAmount)
		assert.Contains(t, plan.ModelScope, MonthlyModelQwen)
	}
	classroom, err := classroomDesiredPlan(false, false, 2_500_000)
	require.NoError(t, err)
	assert.Equal(t, 10, classroom.DurationValue)
	assert.Equal(t, 5.0, classroom.PriceAmount)
	assert.Contains(t, classroom.ModelScope, ClassroomModelQwen)
}

func TestBigfishExpressionAppliesMultiplierOnceAcrossAllTokenLegsAndWindows(t *testing.T) {
	setupBigfishProductsTest(t)
	zone, err := time.LoadLocation("Asia/Shanghai")
	require.NoError(t, err)
	for _, test := range []struct {
		name   string
		model  string
		time   time.Time
		params billingexpr.TokenParams
		quota  int
	}{
		{"ga-input", ClassroomModelV4GA, time.Time{}, billingexpr.TokenParams{P: 1_000_000}, 900_000},
		{"ga-cache", ClassroomModelV4GA, time.Time{}, billingexpr.TokenParams{CR: 1_000_000}, 30_000},
		{"ga-output", ClassroomModelV4GA, time.Time{}, billingexpr.TokenParams{C: 1_000_000}, 2_700_000},
		{"peak-input", ClassroomModelV41, time.Date(2026, 10, 12, 9, 0, 0, 0, zone), billingexpr.TokenParams{P: 1_000_000}, 600_000},
		{"peak-cache", ClassroomModelV41, time.Date(2026, 10, 12, 9, 0, 0, 0, zone), billingexpr.TokenParams{CR: 1_000_000}, 12_000},
		{"peak-output", ClassroomModelV41, time.Date(2026, 10, 12, 9, 0, 0, 0, zone), billingexpr.TokenParams{C: 1_000_000}, 2_400_000},
		{"offpeak-input", ClassroomModelV41, time.Date(2026, 10, 12, 12, 0, 0, 0, zone), billingexpr.TokenParams{P: 1_000_000}, 300_000},
		{"offpeak-cache", ClassroomModelV41, time.Date(2026, 10, 12, 12, 0, 0, 0, zone), billingexpr.TokenParams{CR: 1_000_000}, 6_000},
		{"weekend-output", ClassroomModelV41, time.Date(2026, 10, 17, 10, 0, 0, 0, zone), billingexpr.TokenParams{C: 1_000_000}, 1_200_000},
	} {
		t.Run(test.name, func(t *testing.T) {
			price, err := GetProductPriceSnapshot(ProductTypePackDeepSeekBigfish, test.model, BigfishPriceVersion)
			require.NoError(t, err)
			snapshot := &billingexpr.BillingSnapshot{BillingMode: "tiered_expr", ExprString: price.BillingExpression, ExprHash: billingexpr.ExprHashString(price.BillingExpression), GroupRatio: 1, QuotaPerUnit: common.QuotaPerUnit, ProductType: price.ProductType, ProductMultiplier: price.BillingMultiplier, PriceVersion: price.PriceVersion}
			result, err := billingexpr.ComputeTieredQuotaWithRequest(snapshot, test.params, billingexpr.RequestInput{EvaluationUnix: test.time.Unix()})
			require.NoError(t, err)
			assert.Equal(t, test.quota, result.ActualQuotaAfterGroup)
		})
	}
}

func TestBigfishIFLinkPaySharedPoolKeyExpiryAndCrossTierLimit(t *testing.T) {
	for index := range 3 {
		t.Run([]string{"lite", "pro", "max"}[index], func(t *testing.T) {
			plans := setupBigfishProductsTest(t)
			plan := plans[index]
			other := plans[(index+1)%3]
			user := createV1ContractUser(t, "bigfish-purchase-user")
			order, _, err := CreateSubscriptionOrder(user.Id, plan.Id, "bigfish-first", PaymentMethodIFLinkPay, PaymentProviderIFLinkPay, true)
			require.NoError(t, err)
			retry, _, err := CreateSubscriptionOrder(user.Id, plan.Id, "bigfish-retry", PaymentMethodIFLinkPay, PaymentProviderIFLinkPay, true)
			require.NoError(t, err)
			assert.Equal(t, order.TradeNo, retry.TradeNo)
			_, _, err = CreateSubscriptionOrder(user.Id, other.Id, "bigfish-other", PaymentMethodIFLinkPay, PaymentProviderIFLinkPay, true)
			require.ErrorContains(t, err, "待支付")
			receipt := PaymentReceipt{Amount: decimal.NewFromFloat(plan.PriceAmount), Currency: "CNY", ProviderTradeNo: "bigfish-provider-receipt"}
			require.NoError(t, CompleteSubscriptionOrderWithReceipt(order.TradeNo, PaymentProviderIFLinkPay, PaymentMethodIFLinkPay, receipt))
			require.NoError(t, CompleteSubscriptionOrderWithReceipt(order.TradeNo, PaymentProviderIFLinkPay, PaymentMethodIFLinkPay, receipt))
			completed := GetSubscriptionOrderByTradeNo(order.TradeNo)
			require.NotNil(t, completed.UserSubscriptionId)
			var sub UserSubscription
			require.NoError(t, DB.First(&sub, *completed.UserSubscriptionId).Error)
			assert.Equal(t, plan.TotalAmount, sub.AmountTotal)
			assert.Equal(t, int64(15*24*3600), sub.EndTime-sub.StartTime)
			var bindings []SubscriptionKeyBinding
			require.NoError(t, DB.Where("user_subscription_id = ?", sub.Id).Find(&bindings).Error)
			require.Len(t, bindings, 1)
			var token Token
			require.NoError(t, DB.First(&token, bindings[0].TokenId).Error)
			assert.Equal(t, sub.EndTime, token.ExpiredTime)
			assert.Equal(t, ProductTypePackDeepSeekBigfish, token.ProductType)
			assert.False(t, sub.AllowWalletOverflow)
			_, err = PreConsumeUserSubscription("bigfish-flash-a", user.Id, ClassroomModelV4GA, 0, 100, sub.Id)
			require.NoError(t, err)
			_, err = PreConsumeUserSubscription("bigfish-flash-b", user.Id, ClassroomModelV41, 0, 200, sub.Id)
			require.NoError(t, err)
			_, err = PreConsumeUserSubscription("bigfish-disallowed", user.Id, "deepseek-v4-pro-0813", 0, 100, sub.Id)
			require.Error(t, err)
			require.NoError(t, DB.First(&sub, sub.Id).Error)
			assert.Equal(t, int64(300), sub.AmountUsed)
			_, err = PreConsumeUserSubscription("bigfish-drain", user.Id, ClassroomModelV4GA, 0, sub.AmountTotal-300, sub.Id)
			require.NoError(t, err)
			_, err = PreConsumeUserSubscription("bigfish-exhausted", user.Id, ClassroomModelV41, 0, 1, sub.Id)
			require.Error(t, err)
			require.NoError(t, DB.Model(&sub).Updates(map[string]interface{}{"end_time": common.GetTimestamp() - 1, "status": "expired"}).Error)
			_, err = PreConsumeUserSubscription("bigfish-expired", user.Id, ClassroomModelV4GA, 0, 1, sub.Id)
			require.Error(t, err)
			_, _, err = CreateSubscriptionOrder(user.Id, other.Id, "bigfish-after-expiry", PaymentMethodIFLinkPay, PaymentProviderIFLinkPay, true)
			require.ErrorContains(t, err, "限购一份")
		})
	}
}

func TestBigfishConcurrentOrdersCannotReserveDifferentTiers(t *testing.T) {
	plans := setupBigfishProductsTest(t)
	user := createV1ContractUser(t, "bigfish-concurrent-user")
	var start sync.WaitGroup
	start.Add(1)
	results := make(chan error, 2)
	for index := range 2 {
		go func(index int) {
			start.Wait()
			_, _, err := CreateSubscriptionOrder(user.Id, plans[index].Id, []string{"bigfish-race-a", "bigfish-race-b"}[index], PaymentMethodIFLinkPay, PaymentProviderIFLinkPay, true)
			results <- err
		}(index)
	}
	start.Done()
	first, second := <-results, <-results
	assert.True(t, (first == nil) != (second == nil), "exactly one tier may reserve the promotion")
	var count int64
	require.NoError(t, DB.Model(&SubscriptionOrder{}).Where("user_id = ? AND product_family = ?", user.Id, BigfishProductFamily).Count(&count).Error)
	assert.Equal(t, int64(1), count)
}
